import {expect} from '@playwright/test';import {test} from './fixtures.js';
const token='e'.repeat(64),digest='a'.repeat(64),request='11111111-1111-4111-8111-111111111111';
const target={id:'prepared',credential_alias:'admin',review_digest:digest,artifact_bytes:1024,running:false,plan:{address:'192.0.2.20',port:22,admin_user:'bootstrap',controller_ip:'192.0.2.10',host_key:'ssh-ed25519 test-host',inventory_key:'ssh-ed25519 test-inventory',admin_key_fingerprint:'SHA256:'+'a'.repeat(43),artifact_sha256:'b'.repeat(64),architecture:'amd64'}};
async function open(page){await page.goto('/');await page.getByLabel('Admin read token').fill('a'.repeat(64));await page.getByRole('button',{name:'Connect read-only'}).click();await page.getByRole('link',{name:'Servers',exact:true}).click();await page.locator('#ssh-target-registration > summary').click();await page.getByLabel('Separate bootstrap token').fill(token);await page.getByRole('button',{name:'Load bootstrap targets and status'}).click();await page.getByLabel('Prepared bootstrap target').selectOption('prepared')}
test('prepared installation uses exact review and separately explicit unknown retry',async({page})=>{let operation;const posts=[];await page.route('**/admin/api/v1/bootstrap',route=>{if(route.request().method()==='GET')return route.fulfill({json:{targets:[{...target,...(operation?{operation}: {})}]}});const body=route.request().postDataJSON();posts.push(body);operation={target_id:target.id,review_digest:digest,request_id:body.request_id,state:'unknown',attempts:posts.length};return route.fulfill({status:202,json:operation})});await open(page);await expect(page.getByRole('button',{name:'Install reviewed inventory'})).toBeDisabled();await page.getByLabel('Approve prepared-host installation').check();await page.getByLabel('Separate bootstrap token').fill(token);await page.getByRole('button',{name:'Install reviewed inventory'}).click();await expect(page.getByText(/Request durably recorded with unknown/)).toBeVisible();expect(posts[0].review_digest).toBe(digest);expect(posts[0].retry_unknown).toBe(false);await expect(page.getByLabel('Separate bootstrap token')).toHaveValue('');await page.getByLabel('Separate bootstrap token').fill(token);await page.getByRole('button',{name:'Load bootstrap targets and status'}).click();await page.getByLabel('Prepared bootstrap target').selectOption('prepared');await page.getByLabel('Approve prepared-host installation').check();await expect(page.getByRole('button',{name:'Retry identical bootstrap plan'})).toBeDisabled();await page.getByLabel('Confirm same-plan bootstrap retry').check();await page.getByLabel('Separate bootstrap token').fill(token);await page.getByRole('button',{name:'Retry identical bootstrap plan'}).click();expect(posts[1].request_id).toBe(posts[0].request_id);expect(posts[1].retry_unknown).toBe(true)});
test('closing pending bootstrap clears credentials and ignores late reply',async({page})=>{let finish;const pending=new Promise(r=>finish=r);let started=false;await page.route('**/admin/api/v1/bootstrap',async route=>{if(route.request().method()==='GET')return route.fulfill({json:{targets:[target]}});const body=route.request().postDataJSON();started=true;await pending;try{await route.fulfill({status:202,json:{target_id:target.id,review_digest:digest,request_id:body.request_id,state:'installed',attempts:1}})}catch{}});await open(page);await page.getByLabel('Approve prepared-host installation').check();await page.getByLabel('Separate bootstrap token').fill(token);await page.getByRole('button',{name:'Install reviewed inventory'}).click();await expect.poll(()=>started).toBe(true);await page.getByRole('button',{name:'Cancel bootstrap request view'}).click();finish();await expect(page.getByText(/Closing or cancelling does not undo installation/)).toBeVisible();await expect(page.getByText(/Installation is recorded/)).toHaveCount(0);await expect(page.getByLabel('Separate bootstrap token')).toHaveValue('')});
